"""Head-to-head evaluation between any two agents.

Protocol (shared by every experiment in the project):
  * K opening positions are generated by playing `opening_plies` uniformly
    random moves from the start position (fixed seed => identical openings
    for every match-up);
  * every opening is played twice, once with each agent as black;
  * results are reported from agent A's perspective with a 95% CI on the score.
"""
from __future__ import annotations

import math
import random
import time
from concurrent.futures import ProcessPoolExecutor
from dataclasses import dataclass, field

from othello.agents.registry import make_agent
from othello.env import BLACK, OthelloEnv


def make_openings(env: OthelloEnv, k: int, plies: int, seed: int) -> list[list[int]]:
    rng = random.Random(seed)
    openings = []
    while len(openings) < k:
        s, moves = env.initial_state(), []
        for _ in range(plies):
            if env.is_terminal(s):
                break
            m = rng.choice(env.legal_moves(s))
            moves.append(m)
            s = env.step(s, m)
        if not env.is_terminal(s):
            openings.append(moves)
    return openings


def play_game(env, black, white, opening):
    s = env.initial_state()
    for m in opening:
        s = env.step(s, m)
    black.reset(), white.reset()
    moves = []
    while not env.is_terminal(s):
        agent = black if s.player == BLACK else white
        m = agent.act(s)
        moves.append(m)
        s = env.step(s, m)
    return env.score(s), moves


def _worker(args):
    board_size, spec_a, spec_b, jobs, seed = args
    env = OthelloEnv(board_size)
    a = make_agent(spec_a, env, seed=seed)
    b = make_agent(spec_b, env, seed=seed + 1)
    out = []
    for idx, opening, a_is_black in jobs:
        black, white = (a, b) if a_is_black else (b, a)
        diff, moves = play_game(env, black, white, opening)
        a_diff = diff if a_is_black else -diff
        out.append({"idx": idx, "a_is_black": a_is_black, "opening": opening,
                    "moves": moves, "black_minus_white": diff, "a_margin": a_diff})
    return out


@dataclass
class MatchResult:
    wins: int
    draws: int
    losses: int
    mean_margin: float
    seconds: float
    games: list = field(default_factory=list, repr=False)

    @property
    def n(self):
        return self.wins + self.draws + self.losses

    @property
    def score(self):
        return (self.wins + 0.5 * self.draws) / self.n

    @property
    def win_rate(self):
        return self.wins / self.n

    def ci95(self):
        """Normal-approximation 95% half-width on the score."""
        p = self.score
        return 1.96 * math.sqrt(max(p * (1 - p), 1e-12) / self.n)

    def summary(self) -> dict:
        return {"games": self.n, "wins": self.wins, "draws": self.draws, "losses": self.losses,
                "win_rate": self.win_rate, "score": self.score, "score_ci95": self.ci95(),
                "mean_margin": self.mean_margin, "seconds": self.seconds}


def play_match(board_size: int, spec_a: dict, spec_b: dict, n_openings: int,
               opening_plies: int = 4, seed: int = 0, workers: int = 8,
               keep_games: bool = False) -> MatchResult:
    env = OthelloEnv(board_size)
    openings = make_openings(env, n_openings, opening_plies, seed)
    jobs = [(i, op, a_black) for i, op in enumerate(openings) for a_black in (True, False)]
    chunks = [jobs[w::workers] for w in range(workers)]
    t0 = time.time()
    args = [(board_size, spec_a, spec_b, c, seed * 1000 + 2 * w) for w, c in enumerate(chunks) if c]
    if workers > 1:
        with ProcessPoolExecutor(workers) as ex:
            results = [g for part in ex.map(_worker, args) for g in part]
    else:
        results = [g for a in args for g in _worker(a)]
    secs = time.time() - t0
    results.sort(key=lambda g: (g["idx"], not g["a_is_black"]))
    w = sum(g["a_margin"] > 0 for g in results)
    d = sum(g["a_margin"] == 0 for g in results)
    l = len(results) - w - d
    margin = sum(g["a_margin"] for g in results) / len(results)
    return MatchResult(w, d, l, margin, secs, results if keep_games else [])
